import type {Task} from '../types';

export const GRADE4_TEACHING: Record<string, Partial<NonNullable<Task['lesson']>>> = {
  'g4_l1': {"concept": "Организуем файлы проекта", "explanation": "У каждого файла есть имя и расширение после точки. Имя помогает узнать содержание, а расширение — тип файла. Документ содержит текст, презентация состоит из слайдов, таблица хранит данные в ячейках. Фото и рисунки относятся к медиа. Папки помогают быстро находить материалы: сначала узнай тип, затем выбери подходящую папку.", "example": "Файл «План_Экскурсии.docx» — текстовый документ, даже если в его имени есть слово «экскурсия». Расширение .docx помогает отличить его от фотографии .png.", "goal": "Разложи все файлы по папкам, ориентируясь на расширения.", "steps": ["Прочитай имя и расширение первого файла.", "Перетащи его в папку подходящего типа; на сенсорном экране можно выбрать файл и папку.", "Если файл оказался не там, перенеси его снова. Проверь остальные файлы."], "success": "Все файлы находятся в подходящих папках, тренажёр показывает завершение."},
  'g4_l2': {"concept": "Печатаем точно и меняем раскладку", "explanation": "Клавиатура передаёт компьютеру нажатия, процессор выполняет команды, а оперативная память держит данные текущей работы. В этой практике мы тренируем точную печать. Фраза содержит русские и английские буквы: раскладку нужно менять. Большую букву вводят с Shift, пробел — клавишей пробела. Скорость придёт с тренировкой: сначала следи за текущим символом и исправляй ошибки.", "example": "В словах «ПК и CPU» сначала нужна русская раскладка. Перед CPU переключись на английскую и используй Shift для заглавных букв; перед следующими русскими словами верни раскладку.", "goal": "Напечатай показанную фразу с её пробелами и заглавными буквами.", "steps": ["Нажми на область тренажёра, чтобы начать ввод с клавиатуры.", "Смотри на выделенный символ и меняй раскладку между русскими и английскими буквами.", "Если ошибся, исправь символ клавишей Backspace и продолжи."], "success": "Вся фраза введена верно, показан результат тренировки."},
  'g4_l3': {"concept": "Число из двоичных разрядов", "explanation": "Бит может быть выключен или включён: 0 или 1. В тренажёре каждому переключателю соответствует вес, подписанный над ним. Включённые веса складываются, выключенные ничего не добавляют. Веса растут вдвое: 1, 2, 4, 8. Чтобы собрать число, выбирай веса так, чтобы сумма совпала с целью. Повторное нажатие выключает лишний вес.", "example": "Число 6 можно собрать из весов 4 и 2: 4 + 2 = 6. Вес 1 оставляем выключенным, иначе получится 7. Это пример; в раунде будет другая цель.", "goal": "Собери число каждого раунда включёнными переключателями.", "steps": ["Сравни целевое число и текущую сумму.", "Включи подходящие веса; если сумма слишком велика, выключи лишний.", "После совпадения суммы с целью переходи к следующему раунду."], "success": "Пройдены все раунды двоичного тренажёра."},
  'g4_l4': {"concept": "Сжатие повторов: число и символ", "explanation": "Сжатие помогает записывать данные короче так, чтобы их можно было восстановить. Метод RLE заменяет группу одинаковых символов числом повторов и самим символом. Считаются только символы, стоящие подряд. Когда символ меняется, начинается новая группа. Порядок групп сохраняется. Такая запись выгодна для длинных повторов, но не обязательно для любого текста.", "example": "КККЛЛК превращается в 3К2Л1К. Последнюю К нельзя добавить к первой группе: между ними стоят две Л. Чтобы восстановить запись, повторяем каждый символ указанное число раз.", "goal": "Выбери RLE-запись показанной последовательности.", "steps": ["Раздели последовательность на группы одинаковых символов подряд.", "Для каждой группы запиши мысленно количество, затем символ.", "Сравни полученную запись с вариантами и выбери совпадающий."], "success": "Выбран вариант, сохраняющий количество символов и порядок групп."},
  'g4_l5': {"concept": "Собираем число с пятью разрядами", "explanation": "Пятый разряд добавляет вес 16. Правило осталось прежним: сумма складывается только из включённых весов. Удобно начать с самого большого веса, который не превышает цель. Затем вычти его из цели и подбери веса для остатка. Каждый вес можно использовать только один раз. Проверяй сумму после изменения, чтобы заметить лишний переключатель.", "example": "Для числа 22 берём 16, остаётся 6. Остаток собираем как 4 + 2: вместе 16 + 4 + 2 = 22. В самостоятельном раунде подбери веса для его числа.", "goal": "Пройди раунды с пятью переключателями.", "steps": ["Прочитай цель и веса, не путай положение переключателя с его значением.", "Выбери вес и посчитай, сколько ещё не хватает.", "Продолжай подбор; выключай лишние веса, пока сумма не совпадёт с целью."], "success": "Все целевые числа собраны, показано завершение."},
  'g4_l6': {"concept": "Читаем блок-схему", "explanation": "Алгоритм — последовательность понятных действий. Блок-схема показывает её фигурами и стрелками. Овал отмечает начало или конец, прямоугольник — действие. Ромб содержит вопрос, ответ на который определяет дальнейший путь. Обычно у него две стрелки: «Да» и «Нет». Читать схему нужно по стрелкам, выбирая ветку по ответу на вопрос.", "example": "Для прогулки схема может спросить: «Идёт дождь?» При ответе «Да» выполняем действие «Возьми зонт», при «Нет» идём дальше без этого действия. Вопрос и действие занимают разные блоки.", "goal": "Выбери фигуру, которой обозначают проверку условия.", "steps": ["Определи: речь о начале, действии или вопросе с двумя исходами?", "Вспомни роль каждой фигуры.", "Выбери подходящий вариант и прочитай разбор ответа."], "success": "Выбрана фигура для развилки по условию."},
  'g4_l7': {"concept": "Сортируем соседние числа", "explanation": "Сортировка по возрастанию располагает числа от меньшего к большему. Пузырьковый способ сравнивает два соседних числа. Если левое больше правого, меняем их местами. Если левое меньше или равно правому, оставляем пару как есть. После одного прохода могут остаться другие неверные пары, поэтому сравнения повторяются. В тренажёре следи за выделенной парой, а не пытайся переставить сразу весь ряд.", "example": "В ряду 7, 3, 5 сначала сравним 7 и 3 и поменяем их: 3, 7, 5. Затем поменяем 7 и 5: 3, 5, 7. Каждое действие касается только соседей.", "goal": "Расставь числа по возрастанию, решая для каждой выделенной пары, нужна ли перестановка.", "steps": ["Посмотри на два выделенных числа.", "Если левое больше, выбери обмен; иначе оставь порядок.", "Продолжай сравнения до завершения сортировки."], "success": "Ряд отсортирован, тренажёр показывает успешный результат."},
  'g4_l8': {"concept": "Ищем число в дереве", "explanation": "Дерево состоит из узлов с числами и ветвей между ними. В этом дереве меньшие числа расположены слева от узла, большие — справа. Начинай с верхнего узла и сравнивай его число с целью. Если цель меньше, продолжай по левой ветви; если больше — по правой. Если числа равны, поиск закончен. Это поиск в дереве: мы выбираем ветвь, а не середину нарисованного ряда.", "example": "Пусть верхний узел равен 40, а цель — 32. Идём налево; если следующий узел равен 25, теперь идём направо. Направление каждый раз зависит от нового сравнения.", "goal": "Найди целевое число в показанном дереве.", "steps": ["Прочитай цель и число верхнего узла.", "Выбери узел по подходящей ветви: меньшая цель — слева, большая — справа.", "Повторяй сравнение до узла с целевым числом."], "success": "Найден именно узел с целью, показано завершение поиска."},
  'g4_l9': {"concept": "Считаем сокращение вариантов", "explanation": "Эффективность можно сравнивать по числу действий, нужных для результата. Один способ проверяет кандидатов по очереди. Другой при подходящих условиях сокращает множество вариантов вдвое. Для такой задачи считай оставшееся количество после каждого шага. Остановись, когда остаётся один кандидат. Число делений пополам не всегда равно числу всех действий реальной программы.", "example": "Для восьми кандидатов последовательность такая: 8 → 4 → 2 → 1. Здесь три сокращения пополам. Стрелки показывают шаги, а не количество кандидатов.", "goal": "Посчитай, сколько сокращений пополам оставит одного кандидата.", "steps": ["Начни с количества, указанного в вопросе.", "Последовательно дели его на два до единицы.", "Посчитай деления и выбери вариант с этим числом шагов."], "success": "Выбран верный результат подсчёта шагов."},
  'g4_l10': {"concept": "Планируем путь по клеткам", "explanation": "На карте каждый шаг перемещает дрона в соседнюю клетку. Команды move_right, move_left, move_down и move_up задают направления относительно экрана. Вправо всегда означает к правому краю карты, вниз — к нижнему. Команды выполняются сверху вниз; поворачивать персонажа для них не нужно. Стена запрещает вход в клетку, поэтому маршрут должен её обходить. Планируй по участкам и после запуска сравнивай результат со своим планом.", "example": "Чтобы пройти одну клетку вверх и две влево на свободной карте, запишем drone.move_up(), затем две строки drone.move_left(). Это пример команд, а не готовый маршрут твоего задания.", "goal": "Составь программу, которая доведёт дрона до цели, обходя стены.", "steps": ["Найди старт, цель и клетки со стенами.", "Составь путь по свободным соседним клеткам и запиши по одной команде на строку.", "Запусти программу; при ошибке найди первый неверный шаг, исправь его и повтори запуск."], "success": "Дрон дошёл до цели без столкновения со стенами."},
  'g4_l11': {"concept": "Планируем движение по участкам", "explanation": "Траектория — путь, по которому движется герой. На клеточной карте она состоит из шагов вверх, вниз, влево и вправо. Зигзаг появляется, когда направления чередуются. Но красивый узор не важнее безопасности: каждый шаг должен вести в свободную клетку. Сначала проверь путь по карте, затем запиши команды в таком же порядке. Если участок повторяется, это помогает заметить закономерность.", "example": "На свободной карте шаг вниз, шаг вправо, снова вниз и вправо дают лестницу из четырёх шагов. На карте со стенами такой узор может не подойти: проверь каждую клетку.", "goal": "Доведи дрона до цели, спланировав свободные участки пути.", "steps": ["Найди старт, цель и стены.", "Проследи путь по соседним свободным клеткам и запиши команды по порядку.", "Запусти программу; сравни пройденный путь с планом и исправь первый неверный шаг."], "success": "Дрон достиг цели без входа в стену."},
  'g4_l12': {"concept": "Как кадры создают движение", "explanation": "Анимация состоит из отдельных изображений — кадров. В соседних кадрах положение или поза героя немного меняется. При последовательном показе мы видим движение. FPS означает количество показанных кадров за одну секунду. Если за то же время показать больше промежуточных положений, движение обычно выглядит плавнее. Одно число FPS не гарантирует качество: важны также сами кадры и равномерный показ.", "example": "Мяч нарисован сверху, посередине и снизу листа. Если показывать эти картинки по очереди, он движется вниз. Добавив картинки между ними, можно уменьшить заметные скачки.", "goal": "Выбери, что измеряет FPS.", "steps": ["Вспомни, что в анимации называют кадром.", "Определи, что считают за одну секунду.", "Выбери соответствующий вариант и прочитай объяснение."], "success": "Выбран вариант о количестве кадров за секунду."},
  'g4_l13': {"concept": "Привязываем звук к событию", "explanation": "Событие — то, что произошло в игре: нажатие кнопки, сбор предмета или завершение уровня. Звуковой эффект помогает заметить результат действия. Поэтому его запускают в связи с нужным событием, а не непрерывно. Например, звук прыжка должен совпадать с началом прыжка. Если игра не разрешила прыгнуть, один лишь звук может запутать игрока. Звук полезно дополнять видимым изменением, чтобы игра была понятна и без него.", "example": "Когда герой подбирает звезду, она исчезает, счёт увеличивается и звучит короткий сигнал. Если тот же сигнал проигрывать каждую секунду, по нему уже нельзя понять, собрана ли звезда.", "goal": "Выбери момент запуска звука прыжка в описанной игре.", "steps": ["Найди событие, которому принадлежит эффект.", "Сравни варианты: какой совпадает с этим событием?", "Выбери ответ и прочитай разбор."], "success": "Выбран запуск звука вместе с событием прыжка."},
  'g4_l14': {"concept": "Собираем каркас игрового экрана", "explanation": "Макет — план размещения элементов до создания работающей игры. Верхняя панель показывает сведения об игроке. Главная область отведена игре или герою, а главное действие — управлению. У каждой области своя задача: элементы нельзя размещать случайно. В этом тренажёре ты собираешь расположение из готовых деталей. Это ещё не программирование прыжка или счётчика: сейчас проверяется устройство экрана.", "example": "Для игры с воздушным шаром сведения об игроке помещаем сверху, сам шар — в главной области, а кнопку запуска — в области действия. Так игрок сначала видит сцену и понимает, чем управлять.", "goal": "Заполни требуемые области макета подходящими элементами.", "steps": ["Прочитай названия областей и описание доступных деталей.", "Выбери деталь и нажми на подходящую область либо перетащи её туда.", "Если деталь не подходит, прочитай сообщение и выбери другую область. Заполнив макет, нажми «Запустить приложение»."], "success": "Все требуемые области заполнены подходящими элементами, проверка успешна."},
  'g4_l15': {"concept": "Сообщение связывает спрайты", "explanation": "Спрайты могут иметь отдельные программы. Изменение координат одного героя само по себе не запускает код другого. Сообщение позволяет сообщить о событии нескольким спрайтам. Получатель реагирует, только если у него есть обработчик сообщения с тем же именем. Разные получатели могут выполнить разные действия. Это внутренний сигнал проекта, а не письмо человеку.", "example": "Кнопка отправляет сообщение «Начать раунд». Герой по этому сообщению появляется на старте, а таймер начинает отсчёт. Оба имеют собственные обработчики одного имени.", "goal": "Выбери, для чего спрайту отправлять сообщение.", "steps": ["Отдели действие самого спрайта от связи с другими спрайтами.", "Вспомни, что запускает обработчик получателя.", "Выбери назначение сообщения и прочитай разбор."], "success": "Выбран ответ о запуске обработчиков других спрайтов."},
  'g4_l16': {"concept": "Повторяем участок, затем продолжаем", "explanation": "Цикл повторяет выбранные команды указанное число раз. В записи for i in range(N): число N определяет количество повторов. После двоеточия повторяемые команды записывают с отступом на следующей строке. Команда без этого отступа после блока выполняется один раз после всех повторов. Сначала найди одинаковые шаги маршрута, затем отдели от них продолжение. Цикл не обходит стены сам: каждый повтор должен быть безопасным.", "example": "Два шага вправо и один вниз можно записать так:\nfor i in range(2):\n    drone.move_right()\ndrone.move_down()\nВниз идём один раз после двух повторов, потому что эта строка без отступа.", "goal": "Доведи дрона до цели, используя цикл для повторяющихся шагов.", "steps": ["По карте посчитай одинаковые шаги свободного участка.", "Запиши цикл с двоеточием и командой с отступом; продолжение маршрута вынеси после блока.", "Запусти программу и проверь, какие шаги повторились. При ошибке поправь число повторов или отступ."], "success": "Дрон достиг цели; повторяемый участок выполнен циклом."},
  'g4_l17': {"concept": "Когда цикл заканчивается", "explanation": "Цикл while проверяет условие перед каждым повтором. Пока условие истинно, выполняется его тело. Если условие стало ложным, цикл заканчивается. Он также может завершиться командой выхода. Когда условие всегда истинно и выхода нет, повторения продолжаются без завершения. Пауза может замедлить такой цикл, но сама по себе не делает его конечным.", "example": "Программа повторяет действие, пока осталось больше нуля попыток. После каждой попытки их число уменьшается; при нуле условие становится ложным. Если счётчик не менять, причина остановки исчезнет.", "goal": "Определи, завершится ли цикл с постоянно истинным условием без команды выхода.", "steps": ["Прочитай условие и проверь, может ли оно измениться.", "Проверь, указана ли команда выхода.", "Выбери ожидаемое поведение цикла."], "success": "Выбран ответ о повторении без завершения."},
  'g4_l18': {"concept": "Выбираем ветку если — иначе", "explanation": "Условие даёт один из двух результатов: истина или ложь. В конструкции if — else при истине выполняется ветка if, при лжи — ветка else. Обе ветки в одной такой проверке не выполняются. Знак >= означает «больше или равно»: подходит и точное равенство. Подставь значение переменной и сначала оцени сравнение. Только после этого выбирай действие.", "example": "Правило: если energy >= 4, начать поход, иначе отдохнуть. При energy = 2 сравнение ложно, поэтому отдыхаем. При energy = 4 условие уже истинно: равенство тоже подходит.", "goal": "Определи, какое действие выполнится при указанном счёте.", "steps": ["Найди значение score и число, с которым его сравнивают.", "Прочитай >= как «больше или равно» и оцени условие.", "Выбери действие только подходящей ветки."], "success": "Выбран вызов из ветки, соответствующей результату сравнения."},
  'g4_l19': {"concept": "Проверяем клетку перед шагом", "explanation": "В игре столкновение означает, что герой встретился с препятствием. Здесь карта разделена на клетки, и стеной занята целая клетка. Шаг в такую клетку вызывает ошибку маршрута. Поэтому перед каждым шагом проверяй следующую клетку. Цель тоже занимает конкретное место: пройти рядом с ней недостаточно. Правильный маршрут должен закончиться в клетке цели.", "example": "Если справа от героя стена, команда вправо столкнётся с ней. Можно искать обход через свободные клетки сверху или снизу, но сначала убедись, что весь обход свободен.", "goal": "Доведи дрона точно до цели, проверяя клетки на пути.", "steps": ["Отметь стены и положение цели.", "Перед каждой командой мысленно передвинь дрона на одну клетку и проверь её.", "Запусти маршрут; если произошло столкновение, исправь команду, которая ведёт в стену."], "success": "Дрон находится в клетке цели, столкновений нет."},
  'g4_l20': {"concept": "Считаем одинаковые группы", "explanation": "Данные задачи подсказывают, какую операцию выбрать. Если есть несколько одинаковых групп, общий результат удобно находить умножением. Первый множитель — количество групп, второй — количество предметов в каждой. Звёздочка * в программе обозначает умножение. Сложение двух чисел не заменяет подсчёт одинаковых групп. После расчёта подпиши единицу: монеты, очки или предметы.", "example": "Четыре пакета по две наклейки дают 4 * 2 = 8 наклеек. Выражение 4 + 2 считает сумму двух чисел, но не все наклейки в четырёх пакетах.", "goal": "Выбери формулу общего количества монет во всех сундуках.", "steps": ["Найди количество сундуков и монет в одном сундуке.", "Определи операцию для одинаковых групп.", "Выбери выражение и проверь, что результат означает монеты во всех сундуках."], "success": "Выбрана формула умножения количества сундуков на монеты в каждом."},
  'g4_l21': {"concept": "И: проверяем оба условия", "explanation": "Логическое значение отвечает на вопрос: условие выполнено или нет. В схеме это включённый или выключенный сигнал. Правило И, или AND, даёт включённый выход только при двух включённых входах. Одного входа недостаточно. Чтобы получить выключенный выход, достаточно выключить хотя бы один вход. Перед проверкой прочитай, какое состояние требуется в текущем раунде.", "example": "Чтобы открыть шкаф, нужны пропуск И разрешение учителя. Один пропуск без разрешения не подходит; одно разрешение без пропуска тоже. Оба условия должны выполняться одновременно.", "goal": "Настрой входы A и B по правилу И для каждого раунда.", "steps": ["Прочитай требуемое состояние выхода.", "Переключи входы A и B и предскажи результат по правилу И.", "Нажми «Проверить схему»; при ошибке пересмотри состояние входов."], "success": "Все раунды схемы пройдены."},
  'g4_l22': {"concept": "Счёт нового раунда и рекорд", "explanation": "Переменная хранит текущее значение под именем. Счёт меняется, когда игрок получает очки. Начальное значение нужно задать отдельно: программа не обязана обнулять его сама. При новом раунде в той же игре старый счёт останется, если его не заменить. Рекорд — другое значение: его обычно сохраняют, чтобы сравнивать достижения. Не путай начало раунда со сбросом всех данных.", "example": "В раунде набрано 12 очков. Команда score = 0 начинает следующий раунд с нуля, а переменная record может по-прежнему хранить 12. У этих значений разные задачи.", "goal": "Определи, что произойдёт со счётом при запуске нового раунда без обнуления.", "steps": ["Прочитай, какое значение сохранялось до нового раунда.", "Проверь, присвоено ли новое начальное значение.", "Выбери ожидаемое поведение счёта."], "success": "Выбран ответ о сохранении старого счёта в описанной игре."},
  'g4_l23': {"concept": "Порядок предметов в списке", "explanation": "Список хранит несколько элементов под одним именем. Квадратные скобки отмечают его границы, запятые разделяют элементы. Предметы записаны в определённом порядке. Первый расположен слева, сразу после открывающей скобки. Добавление в конец не перемещает прежний первый элемент. Прочитать список — значит отличить отдельные предметы и их порядок.", "example": "В списке [«Карта», «Верёвка», «Компас»] первой стоит карта. Если добавить фонарь в конец, он станет четвёртым, а карта останется первой.", "goal": "Найди первый предмет в показанном списке.", "steps": ["Найди открывающую квадратную скобку.", "Прочитай первый элемент до запятой.", "Выбери вариант с этим предметом."], "success": "Выбран первый элемент исходного списка."},
  'g4_l24': {"concept": "Суммируем результаты в таблице", "explanation": "Адрес ячейки состоит из буквы столбца и номера строки. В этой таблице итоги каждой строки расположены в столбце D. Чтобы получить общий итог, нужно сложить эти результаты, а не названия предметов и не отдельные исходные значения. Формула начинается со знака =. Функция SUM складывает числа диапазона, а двоеточие означает все ячейки от первой до последней включительно. Ячейку общего итога нельзя включать в её собственную сумму.", "example": "Если в E2, E3 и E4 записаны 6, 8 и 3, формула =SUM(E2:E4) даст 17. В своей таблице найди столбец с итогами и используй его адреса.", "goal": "Вычисли в D5 сумму итогов строк D2–D4.", "steps": ["Найди три числовых итога в столбце D и сложи их мысленно для проверки.", "В поле формулы начни со знака = и укажи диапазон слагаемых для SUM.", "Нажми «Проверить»; если формула не принята, проверь адреса и границы диапазона."], "success": "Формула принята и показан общий числовой итог."},
  'g4_l25': {"concept": "Управление отвечает на действие", "explanation": "Игроку важно понимать связь между нажатием и результатом. Отзывчивое управление быстро отвечает на команду. Анимация и звук помогают заметить, что действие выполнено. Это часть ощущения от игры, которое называют Game Feel. Красивая картинка сама по себе не делает кнопку удобной. Проверяй управление в действии: понятно ли, когда герой начал двигаться и почему остановился.", "example": "В одной игре герой двигается сразу после нажатия и останавливается после отпускания. В другой он реагирует с неожиданной задержкой. Одинаковые рисунки не делают ощущения от управления одинаковыми.", "goal": "Выбери описание отзывчивого управления.", "steps": ["Отдели реакцию на команды от внешнего вида и размера файла.", "Найди вариант, который описывает связь нажатия с действием.", "Выбери ответ и прочитай разбор."], "success": "Выбран ответ об отзывчивости управления."},
  'g4_l26': {"concept": "Подбираем посильное испытание", "explanation": "Новому игроку сначала нужно освоить правило. Если сразу дать сложную комбинацию незнакомых действий, ему будет трудно понять ошибку. Если долго повторять слишком простое, интерес тоже может уменьшиться. Подходящее испытание опирается на уже освоенный навык и добавляет посильную трудность. Состояние увлечённой сосредоточенности называют потоком. Оно не гарантировано всем игрокам: полезно наблюдать и подбирать сложность.", "example": "Сначала игрок учится перепрыгивать одну яму. Затем использует этот навык на коротком участке с двумя ямами. Перед новым препятствием ему дают возможность освоить новое действие.", "goal": "Найди название состояния увлечённой сосредоточенности из вопроса.", "steps": ["Прочитай описание: игроку интересно и задача посильна.", "Отличи это состояние от перегрузки, задержки и скуки.", "Выбери подходящий термин."], "success": "Выбран термин «поток»."},
  'g4_l27': {"concept": "Из плана игры в экран", "explanation": "План игры отвечает на вопросы: кто играет, что делает и как понимает результат. Макет показывает, где будут видны эти сведения и действия. Начни с задачи пользователя, а затем подбирай детали. Верхняя панель помогает ориентироваться, главная область показывает содержание, область действия позволяет управлять. В тренажёре ты проверяешь размещение готовых деталей. Полные правила и работающая программа здесь ещё не создаются.", "example": "В игре про доставку нужен видимый герой, сведения о его состоянии и понятное главное действие. Эти потребности превращаются в области экрана, а не в случайный набор красивых кнопок.", "goal": "Собери макет, в котором есть сведения, главная область и управление.", "steps": ["Прочитай назначение каждой детали, прежде чем выбирать её.", "Размести детали в подходящих областях нажатием или перетаскиванием.", "Проверь заполнение всех областей и нажми «Запустить приложение»."], "success": "Все требуемые области заполнены, макет успешно запущен."},
  'g4_l28': {"concept": "Прыжок и место приземления", "explanation": "Игровая механика — правило действия, доступного герою. В этом задании прыжок отличается от обычного шага: он переносит дрона на две клетки в направлении движения. Промежуточную клетку дрон перескакивает. Но место приземления должно быть свободным и внутри карты. Прыжок не переносит сразу к любой цели. После него проверь новую позицию и спланируй оставшийся путь.", "example": "Дрон смотрит вправо, а через одну клетку есть свободное место. Прыжок переносит его на две клетки вправо; обычный шаг — только на одну. Если место приземления занято, такой прыжок не подходит.", "goal": "Доведи дрона до цели, используя прыжок там, где это помогает пройти препятствие.", "steps": ["Найди старт, препятствие и возможную клетку приземления.", "Запиши доступные команды; для прыжка проверь направление и расстояние в две клетки.", "Запусти программу и при ошибке исправь прыжок или следующие шаги."], "success": "Дрон достиг цели и приземлялся только в свободные клетки."},
  'g4_l29': {"concept": "Наблюдаем, как играет другой человек", "explanation": "Тестирование проверяет, получается ли ожидаемый результат. Автор знает свой замысел и может не заметить непонятное управление. Другой игрок часто действует иначе и помогает обнаружить неудобства. Попроси его выполнить конкретную задачу и наблюдай, где он остановился или ошибся. Запиши действие и результат, затем попробуй повторить проблему. Чтение кода тоже полезно, но не заменяет наблюдение за использованием игры.", "example": "Попроси игрока начать новый раунд. Он нажал на картинку героя, хотя запуск спрятан в маленькой кнопке. Это повод сделать начало понятнее и проверить новый вариант ещё раз.", "goal": "Выбери способ заметить неожиданные действия игроков.", "steps": ["Подумай, какой способ покажет поведение человека, не знающего твоего замысла.", "Сравни наблюдение за игроком с проверкой только самим автором.", "Выбери ответ и прочитай объяснение."], "success": "Выбран способ наблюдать за другими игроками."},
  'g4_l30': {"concept": "Адрес страницы и путь по сети", "explanation": "Веб-адрес указывает, какую страницу мы запрашиваем. В нём есть протокол, доменное имя и путь к странице. Сеть доставляет запрос между устройствами через соединённые узлы. Адрес страницы и маршрут доставки — разные вещи. В тренажёре требуется выбрать именно маршрут: каждый следующий узел должен быть соединён с предыдущим. Учитывай перегруженные узлы и суммарную задержку, чтобы уложиться в предел задания.", "example": "В адресе https://example.org/library протокол — https, домен — example.org, путь — /library. Для доставки по сети путь из двух соединений с задержками 12 и 18 мс займёт 30 мс. Сравнивать нужно сумму, а не только число узлов.", "goal": "Построй маршрут от отправителя к получателю через свободные узлы в пределах задержки.", "steps": ["Найди старт, получателя, связи между узлами и предел задержки.", "Выбирай соединённые узлы по порядку; избегай перегруженных и считай задержки связей.", "Если путь не подходит, начни заново и выбери другой маршрут."], "success": "Пакет доставлен без перегруженных узлов и превышения допустимой задержки."},
  'g4_l31': {"concept": "Запрос, ответ и защищённое соединение", "explanation": "Браузер выступает клиентом: отправляет запрос нужной страницы. Сервер принимает запрос и возвращает ответ с данными. HTTPS защищает передачу между браузером и сервером шифрованием. Это относится к соединению, а не к честности владельца сайта. Мошенническая страница тоже может использовать HTTPS. Поэтому перед вводом данных проверяй сам адрес и то, зачем их просят.", "example": "Ты открываешь каталог библиотеки: браузер запрашивает страницу, сервер присылает её. HTTPS защищает передачу, но не доказывает, что любой адрес со словом «библиотека» принадлежит настоящей библиотеке.", "goal": "Выбери, что означает HTTPS для соединения.", "steps": ["Отдели защиту передачи от обещания безопасности самого сайта.", "Прочитай варианты и найди свойство соединения.", "Выбери ответ и прочитай объяснение."], "success": "Выбран ответ о шифровании соединения."},
  'g4_l32': {"concept": "Передача данных и время маршрута", "explanation": "Скачивание — получение данных из сети на своё устройство. Отправка — передача данных со своего устройства в сеть. В обоих случаях данные проходят через соединённые узлы. В тренажёре оценивается маршрут между показанными отправителем и получателем. Время пути складывается из задержек всех связей. Короткий по числу связей маршрут не всегда быстрее: один медленный участок может увеличить всю сумму.", "example": "Путь с двумя связями по 20 мс занимает 40 мс. Путь с тремя связями по 8 мс занимает 24 мс. Второй длиннее по числу связей, но быстрее по общей задержке.", "goal": "Найди маршрут к получателю, который укладывается в предел задержки.", "steps": ["Найди получателя и доступные связи от текущего узла.", "Сложи задержки выбранных связей и проверь, нет ли перегруженного узла.", "Выбирай узлы по порядку; если путь не подходит, начни заново и сравни другой."], "success": "Доставка завершена без перегрузки и превышения предела."},
  'g4_l33': {"concept": "Проверяем подозрительное письмо", "explanation": "Фишинг — обман, при котором человека побуждают раскрыть секретные данные или выполнить опасное действие. Письмо может выглядеть знакомо, но использовать поддельный адрес. Срочность и обещание неожиданного подарка мешают спокойно проверить просьбу. Пароль нельзя вводить по ссылке из такого письма. Проверяй отдельно отправителя, требование и настоящий адрес ссылки. В тренажёре ты отмечаешь подозрительные места, а не открываешь настоящий сайт.", "example": "Приходит письмо: «Забери подарок за две минуты, сообщи пароль». Даже знакомый логотип не объясняет, зачем нужен пароль. Безопаснее остановиться и показать письмо взрослому, а сервис открыть обычным способом.", "goal": "Найди все признаки опасности в учебном письме.", "steps": ["Прочитай письмо целиком, не выполняя его просьбы.", "Нажимай на подозрительные части: адрес отправителя, срочную просьбу и ссылку.", "Прочитай разбор каждой находки и продолжай, пока не отмечены все признаки."], "success": "Все признаки опасности отмечены, тренажёр показывает завершение."},
  'g4_l34': {"concept": "Не запускаем подозрительную загрузку", "explanation": "Расширение показывает тип файла, но не гарантирует его безопасность. Файл .exe — запускаемая программа; он не обязательно вредоносный. Однако имя skin.png.exe не превращает программу в картинку: важно последнее расширение. Неизвестный источник, обещание читов и предупреждение защиты — причины остановиться. Не отключай антивирус ради запуска. Покажи предупреждение взрослому и проверяй источник до загрузки.", "example": "Файл «Фото_Поход.jpg.exe» заканчивается на .exe: это программа, а не обычная фотография. Не нужно запускать её, чтобы выяснить, безопасна ли она. Имя и источник следует проверить заранее.", "goal": "Оцени предложение из карточки: можно ли доверять такой загрузке.", "steps": ["Найди источник файла, его тип и предупреждения.", "Подумай, есть ли основания доверять запуску неизвестной программы.", "Выбери оценку карточки и прочитай объяснение безопасного действия."], "success": "Выбрана оценка, учитывающая неизвестный источник и предупреждение защиты."},
  'g4_l35': {"concept": "Выбираем пароль и защищаем его", "explanation": "Пароль подтверждает, что входишь именно ты. Длинный, непредсказуемый и отдельный для каждого аккаунта пароль лучше короткого или составленного из личных данных. Имена и годы рождения легко угадать. Длинные последовательности клавиш тоже предсказуемы. Дополнительный фактор помогает защитить вход, но код подтверждения также нельзя сообщать посторонним. Пароли из учебного вопроса публичны: не используй их для настоящего аккаунта.", "example": "«Имя+год рождения» может казаться сложным, но знакомому легко узнать обе части. Для реального аккаунта попроси взрослого помочь создать уникальный пароль и хранить его безопасно.", "goal": "Сравни учебные варианты паролей по длине и предсказуемости.", "steps": ["Исключи очевидные последовательности и варианты с личными данными.", "Сравни оставшиеся варианты: длина полезна вместе с непредсказуемостью.", "Выбери лучший из показанных примеров; не используй его как настоящий пароль."], "success": "Выбран менее предсказуемый длинный вариант из учебного списка."},
  'g4_l36': {"concept": "Готовим примеры для модели", "explanation": "Модель распознавания учится на примерах с подписями категорий. Подпись сообщает, к какой группе относится пример. Неверные подписи мешают обучению, а однообразные примеры не показывают разнообразие группы. В этой практике ты готовишь учебные данные для робота-помощника. Читай названия наборов и рассматривай карточки, прежде чем распределять их. После учебных примеров важно проверять работу на новых, если такая проверка предусмотрена тренажёром.", "example": "Если все подписанные собаки одного цвета, модель может связать ответ с цветом вместо нужных признаков. Полезнее разные собаки с верными подписями и отдельные новые примеры для проверки.", "goal": "Разложи карточки по подписанным наборам и пройди проверку учебных данных.", "steps": ["Прочитай названия двух наборов и описание первой карточки.", "Выбирай карточку и нужный набор либо перетаскивай её; ошибочную подпись исправь.", "Проверь примеры кнопкой тренажёра и выполни следующий этап, если он появился."], "success": "Примеры распределены верно и все предлагаемые этапы проверки завершены."},
  'g4_l37': {"concept": "Проверяем факты в ответе ИИ", "explanation": "Языковая модель может предложить идеи и составить связный текст. Связность и уверенный тон не доказывают точность. В ответе могут быть неверные даты, имена и даже выдуманные источники. Сначала прочитай текст и выдели проверяемые утверждения. Сравни их с учебником, каталогом или другим подходящим надёжным источником. Исправление стиля не заменяет проверку фактов: важно понять содержание и соблюдать правила учебной работы.", "example": "Модель назвала автора рассказа. Переписать предложение своими словами недостаточно: сначала сравни имя с обложкой книги или библиотечным каталогом. После проверки можно исправить текст и объяснить мысль самому.", "goal": "Выбери подходящий порядок работы с текстом нейросети.", "steps": ["Найди вариант, в котором текст сначала читают и проверяют.", "Исключи действия, предполагающие, что ИИ никогда не ошибается.", "Выбери ответ и прочитай разбор."], "success": "Выбран вариант с чтением, проверкой и самостоятельной переработкой."},
  'g4_l38': {"concept": "Соединяем прыжок, шаги и цикл", "explanation": "Большую программу удобнее составлять из небольших участков. Сначала реши, где нужен особый шаг — прыжок через препятствие. Прыжок переносит на две клетки по направлению дрона; место приземления должно быть свободным. Затем спланируй обычные шаги и найди повторяющийся участок. Цикл повторяет только команды с отступом в его теле. Проверь границу между участками: следующий начинает движение с места, где закончился предыдущий.", "example": "На свободном участке два шага влево можно объединить циклом. Прыжок перед этим участком записывается отдельной строкой: он не должен повторяться вместе с каждым шагом. В своём маршруте выбери нужные направления и количество повторов.", "goal": "Доведи дрона до цели, согласовав прыжок, обычные шаги и повторение.", "steps": ["Раздели путь на участок преодоления препятствия и последующие свободные участки.", "Запиши команды и цикл с нужными отступами; мысленно проверь новую позицию после каждого участка.", "Запусти программу и исправляй первый неверный участок, не меняя весь маршрут наугад."], "success": "Дрон достиг цели без столкновения и выхода за карту."},
  'g4_l39': {"concept": "Разбиваем сложную задачу на части", "explanation": "Декомпозиция означает разделение большой задачи на понятные части. Вместо «создать игру» можно отдельно спланировать экран, движение и подсчёт очков. Каждая часть должна иметь понятный результат, который можно проверить. Затем части соединяют и проверяют совместную работу. Запоминание всех команд не заменяет такой план. Если застрял, назови ближайшую небольшую задачу и реши её первой.", "example": "Для викторины нужны вопросы, выбор ответа и показ результата. Сначала можно проверить один вопрос, затем добавить остальные. Так легче найти, какая часть не работает.", "goal": "Выбери приём, который помогает организовать решение сложной задачи.", "steps": ["Подумай, какой вариант делает большую задачу более понятной.", "Отдели планирование частей от скорости печати и заучивания команд.", "Выбери подходящий приём и прочитай разбор."], "success": "Выбран приём разбиения задачи на части."},
  'g4_l40': {"concept": "ИЛИ: проверяем разные сочетания", "explanation": "Правило ИЛИ, или OR, включает выход, если включён хотя бы один вход. Подходит вход A, вход B и оба вместе. Когда выключены оба, выключен и выход. Это отличается от И: для И нужны два включённых входа одновременно. В этом задании проверяется один элемент ИЛИ, а не цепочка разных элементов. Читай цель каждого раунда и выбирай сочетание входов по правилу.", "example": "Звонок можно включить кнопкой у двери ИЛИ кнопкой на пульте. Достаточно любой из них; обе нажатые тоже включают звонок. Чтобы он молчал, обе кнопки должны быть отпущены.", "goal": "Настрой схему ИЛИ для требуемого выхода в каждом раунде.", "steps": ["Прочитай условие раунда: выход должен быть включён или выключен?", "Предскажи результат выбранных входов A и B и переключи их.", "Нажми «Проверить схему»; при ошибке сравни входы с правилом ИЛИ."], "success": "Все раунды элемента ИЛИ пройдены."},
  'g4_l41': {"concept": "Несколько обязательных условий", "explanation": "Логическое И объединяет требования, которые должны выполняться одновременно. Если хотя бы одно обязательное условие ложно, общий результат ложный. Требований может быть два, три и больше. Не заменяй И на ИЛИ: ИЛИ разрешает результат уже при одном выполненном условии. Сначала переведи правило из слов в отдельные проверки. Затем выбери связку, которая сохраняет смысл правила.", "example": "Учебный робот начинает движение, если маршрут задан И батарея заряжена И крышка закрыта. Заряженная батарея не заменяет отсутствующий маршрут: нужны все три требования.", "goal": "Выбери выражение, которое требует выполнения обоих условий запуска.", "steps": ["Выдели в описании два отдельных условия.", "Определи, достаточно ли одного или нужны оба.", "Выбери логическую связку и прочитай разбор."], "success": "Выбрано выражение с И (AND)."},
  'g4_l42': {"concept": "Сигнал тревоги от любого датчика", "explanation": "Датчик передаёт сигнал о наблюдаемом событии. В учебной сигнализации один вход означает движение, второй — пересечение луча. Тревога должна включаться при любом из этих событий, поэтому используется ИЛИ. Оба события одновременно тоже включают тревогу. Только два выключенных входа дают выключенный выход. В практике ты меняешь входы готовой схемы, а не строишь настоящую систему безопасности.", "example": "На складе учебной игры датчик двери ИЛИ датчик окна включает сигнал. Если дверь закрыта, но окно открыли, сигнал всё равно нужен. Правило И в этом примере пропустило бы одиночное событие.", "goal": "Настрой входы схемы ИЛИ по условию текущего раунда.", "steps": ["Свяжи входы A и B с двумя независимыми событиями.", "Прочитай требуемый выход и выбери подходящее сочетание входов.", "Нажми «Проверить схему» и продолжай следующие раунды."], "success": "Все раунды схемы ИЛИ пройдены."},
  'g4_l43': {"concept": "Находим первый неверный шаг", "explanation": "Отладка — поиск причины, по которой программа работает не так, как задумано. На карте удобно проверять команды по одной. После каждой команды отмечай новую клетку. Если очередной шаг ведёт в стену, дальше по этому маршруту дрон уже не сможет идти. Найди первый такой шаг и исправь путь от него. Не меняй сразу все команды: так труднее понять, что помогло.", "example": "План обещает два шага вниз, но второй попадает в стену. Первый шаг может быть правильным; нужно пересмотреть продолжение, а затем проверить новый путь до цели.", "goal": "Составь безопасный маршрут, проверяя команды шаг за шагом.", "steps": ["Найди старт, цель и стену.", "Проследи каждую команду по карте; замени шаг, ведущий в препятствие, и согласуй дальнейший путь.", "Запусти программу и сравни движение с планом."], "success": "Дрон достиг цели, ни одна команда не привела к столкновению."},
  'g4_l44': {"concept": "Проверяем веса двоичных разрядов", "explanation": "Пять переключателей представляют веса 16, 8, 4, 2 и 1. Включённый разряд добавляет свой вес, выключенный добавляет ноль. Положение разряда сохраняет смысл: нельзя удалить нули и считать, что число не изменилось. Сначала подбирай веса, затем проверяй их сумму. Если включён лишний разряд, повторное нажатие выключит его. Точность важнее быстрого угадывания.", "example": "Запись 10010 при весах 16, 8, 4, 2, 1 означает 16 + 2 = 18. Нули показывают, какие веса выключены; число не равно просто «12».", "goal": "Собери целевые числа с помощью пяти разрядов.", "steps": ["Прочитай цель и подписи весов.", "Включи нужные разряды и сравни сумму с целью.", "Исправь лишние или недостающие веса и пройди все раунды."], "success": "Все целевые числа собраны."},
  'g4_l45': {"concept": "Выбираем границы суммы", "explanation": "Диапазон — несколько ячеек таблицы, указанных начальным и конечным адресом. Двоеточие включает обе границы и ячейки между ними. SUM складывает числовые значения диапазона. В тренажёре нужны готовые итоги в столбце D, а не исходные значения в B или C. Общая сумма помещается ниже данных и не должна включать саму себя. Здесь мы готовим числовой итог, а не рисуем диаграмму.", "example": "В F3, F4 и F5 находятся 4, 9 и 2. Диапазон F3:F5 включает все три числа; SUM даёт 15. Если закончить диапазон на F4, последнее слагаемое пропадёт.", "goal": "В D5 посчитай сумму всех трёх итогов D2–D4.", "steps": ["Найди первую и последнюю строки с итогами в столбце D.", "Введи формулу со знаком =, функцией SUM и диапазоном с обеими границами.", "Нажми «Проверить»; при ошибке проверь столбец и номера строк."], "success": "Формула складывает все три итога и принята тренажёром."},
  'g4_l46': {"concept": "Выбираем диаграмму по вопросу", "explanation": "Диаграмма помогает ответить на вопрос о данных. Столбцы удобно сравнивают отдельные категории. Линейный график показывает последовательность значений, например по дням, и помогает увидеть изменение. Круговая диаграмма показывает доли одного целого, а не ход времени. Сначала выясни, что требуется сравнить, затем выбирай изображение. Подписи и единицы нужны, чтобы читатель понимал значения.", "example": "Число книг в разных разделах можно сравнить столбцами. Изменение числа посетителей по месяцам удобно проследить линией. Доли разделов в одной коллекции можно показать кругом, если они составляют целое.", "goal": "Выбери диаграмму, удобную для наблюдения изменения температуры по дням.", "steps": ["Определи, есть ли в задаче последовательность во времени.", "Отдели изменение показателя от долей одного целого.", "Выбери график, который помогает проследить изменение."], "success": "Выбран линейный график для последовательности по дням."},
  'g4_l47': {"concept": "Сверяем формулу с ручным подсчётом", "explanation": "Готовый результат стоит проверить другим способом. Для суммы можно сначала сложить значения вручную, затем сравнить результат формулы. Совпадение полезно, но адреса тоже нужно проверить: формула должна ссылаться именно на нужные ячейки. В этой таблице складываются итоги D2, D3 и D4. Не добавляй D5 — там находится сама общая сумма. Если результат отличается, ищи пропущенное слагаемое или неверный диапазон.", "example": "Итоги за три дня равны 7, 5 и 6, ожидаем 18. Если получилось 12, возможно, не учтён третий день. Проверим адреса слагаемых, а не будем просто вводить число 18 вместо формулы.", "goal": "Вычисли общий итог в D5 и сверь его с ручной суммой.", "steps": ["Выпиши мысленно значения D2–D4 и сложи их.", "Введи формулу суммы нужного диапазона, начиная со знака =.", "Нажми «Проверить» и сравни показанный итог со своим подсчётом."], "success": "Формула принята, её результат совпадает с суммой трёх итогов."},
  'g4_l48': {"concept": "Различаем части веб-адреса", "explanation": "Веб-адрес состоит из частей с разными задачами. Протокол задаёт способ обращения, домен указывает имя сайта. Путь после домена обозначает запрашиваемый ресурс или раздел. Он не обязательно совпадает с папкой на диске: сервер может формировать страницу программой. Фрагмент после # указывает часть страницы, если она определена. Чтобы понять ссылку, разбери её по частям, а не воспринимай как одно длинное слово.", "example": "В https://example.org/books/new#reviews домен — example.org, путь — /books/new, фрагмент — reviews. Путь выбирает ресурс, а фрагмент может указывать раздел отзывов на открытой странице.", "goal": "Найди часть адреса, указывающую запрашиваемый раздел или ресурс.", "steps": ["Отдели протокол и доменное имя.", "Найди часть после домена, которая начинается с /.", "Выбери соответствующий вариант и прочитай разбор."], "success": "Выбран путь ресурса."},
  'g4_l49': {"concept": "DNS находит адрес по имени", "explanation": "Людям удобно пользоваться доменными именами. Для соединения устройству нужен сетевой адрес — IP. DNS помогает найти IP-адрес по имени. Он не хранит все страницы сайта и не проверяет пароль пользователя. После поиска адреса браузер может обратиться к нужному серверу. Верный ответ DNS сам по себе не гарантирует, что содержание сайта честное.", "example": "Ты знаешь имя example.org, но не его сетевой адрес. DNS помогает найти адрес для соединения, а саму страницу затем запрашивает браузер у сервера. Это разные действия.", "goal": "Выбери основную задачу DNS.", "steps": ["Определи, какие две вещи сопоставляет DNS: имя и сетевой адрес.", "Отдели это от хранения страниц, проверки паролей и раздачи Wi-Fi.", "Выбери ответ и прочитай пояснение."], "success": "Выбран поиск IP-адреса по доменному имени."},
  'g4_l50': {"concept": "Доставляем пакет через узлы", "explanation": "При передаче данные делятся на небольшие части — пакеты. У пакета есть данные и служебная информация для доставки. Между отправителем и получателем могут быть промежуточные узлы. В учебном тренажёре ты выбираешь маршрут одного пакета. Каждый следующий узел должен быть соединён с текущим. Проверяй состояние узлов и складывай задержки: достижение получателя ещё не означает выполнение ограничения по времени.", "example": "Один маршрут проходит через три быстрые связи, другой — через две, но одна сильно задерживает пакет. Сравнение суммарного времени помогает выбрать подходящий путь; числа связей недостаточно.", "goal": "Доставь пакет получателю через свободные узлы в пределах допустимой задержки.", "steps": ["Найди получателя, доступные соединения и предел времени.", "Выбирай соединённые узлы по порядку, суммируя задержки и избегая перегрузки.", "Если доставка не подходит по условиям, сбрось маршрут и проверь другую цепочку."], "success": "Пакет доставлен с допустимой задержкой и без перегруженных узлов."},
  'g4_l51': {"concept": "HTML-элемент и цвет его текста", "explanation": "HTML описывает элементы страницы: заголовок, абзац, кнопку. Парный тег окружает содержимое открывающей и закрывающей частями. CSS задаёт оформление, а свойство color меняет цвет букв. Свойство background меняет фон и не заменяет color. В этой практике нужна кнопка с бирюзовым текстом. Само наличие кнопки не создаёт действие при нажатии: сейчас проверяется элемент и его оформление.", "example": "<button style=\"color: orange;\">Начать</button> создаёт кнопку с оранжевыми буквами. Для самостоятельной работы нужен другой цвет из условия.", "goal": "Создай элемент button с цветом текста cyan.", "steps": ["Найди или добавь парный тег button с понятной надписью.", "Задай свойство color для самой кнопки; не перепутай его с фоном.", "Запусти проверку и посмотри результат в предпросмотре."], "success": "Кнопка найдена, цвет её текста соответствует условию."},
  'g4_l52': {"concept": "Повторный проход сортировки", "explanation": "Один проход пузырьковой сортировки не всегда упорядочивает весь ряд. Сравниваются только соседи: если левое число больше, их меняют местами. После прохода большое число оказывается ближе к правому краю. Другие пары могут оставаться в неверном порядке. Продолжай сравнения, пока все числа не стоят по возрастанию. Здесь тренируется пузырьковый способ, а не слияние двух списков.", "example": "Ряд 6, 4, 2 после первого прохода станет 4, 2, 6. Он ещё не готов: пара 4 и 2 требует обмена в следующем проходе.", "goal": "Заверши сортировку, продолжая сравнения выделенных соседей.", "steps": ["Рассмотри текущую выделенную пару.", "Обменяй числа, если левое больше; иначе оставь порядок.", "Продолжай последующие сравнения до завершения тренажёра."], "success": "Все числа расположены по возрастанию."},
  'g4_l53': {"concept": "Используем порядок при поиске", "explanation": "В упорядоченном списке значения идут от меньших к большим. Поэтому сравнение с серединой помогает выбрать часть списка. Если цель меньше среднего значения, большие значения можно исключить. Если больше — исключаются меньшие. Повторяй правило в оставшейся части; при равенстве поиск закончен. Перемешанный список не позволяет надёжно исключить половину этим способом.", "example": "В списке 2, 5, 8, 11, 14 ищем 5. Среднее значение 8 больше цели, поэтому смотрим в левой части. Нам не нужно проверять 11 и 14.", "goal": "Выбери способ поиска, использующий порядок длинного списка.", "steps": ["Обрати внимание, что список уже упорядочен.", "Найди способ, который исключает ненужную часть после сравнения.", "Выбери ответ и прочитай разбор."], "success": "Выбран поиск через середину и нужную половину."},
  'g4_l54': {"concept": "Проверяем непрерывность маршрута", "explanation": "Граф показывает узлы и связи между ними. Маршрут — последовательность узлов, где каждая соседняя пара соединена. Недостаточно просто выбрать нужный конечный узел: до него должен вести допустимый путь. В этой практике не требуется посетить все узлы. Требуется доставить пакет получателю с учётом задержки и перегрузки. Перед последним шагом проверь всю цепочку, а не только её конец.", "example": "Цепочка A → B → E не подходит, если B и E не соединены. Можно искать другой переход из B или вернуться к предыдущему узлу и изменить маршрут.", "goal": "Построй непрерывный допустимый маршрут к получателю.", "steps": ["Найди старт, цель и доступные соединения.", "Выбирай только соединённые узлы и проверяй время пути.", "При ошибке измени цепочку или начни заново."], "success": "Пакет дошёл по связному пути без нарушения ограничений."},
  'g4_l55': {"concept": "Накапливаем сумму по одному значению", "explanation": "Накопитель хранит промежуточную сумму. Перед обработкой списка ему задают ноль. Затем каждое значение добавляют к уже накопленному результату. Запись total = total + цена сначала вычисляет правую часть, затем сохраняет новый итог. Счётчик count + 1 считает предметы, а не их стоимость. Если обнулять total перед каждым добавлением, прежние слагаемые потеряются.", "example": "Цены 3, 8 и 4 дают изменения суммы 0 → 3 → 11 → 15. Каждый шаг сохраняет предыдущую сумму и добавляет следующую цену.", "goal": "Выбери шаблон для общей стоимости товаров.", "steps": ["Определи, нужен итог цен или количество товаров.", "Найди выражение, добавляющее цену к накопленной сумме.", "Выбери ответ и прочитай разбор."], "success": "Выбран накопитель стоимости."},
  'g4_l56': {"concept": "Повторяем прыжки с проверкой позиции", "explanation": "Повторение команды меняет положение дрона каждый раз. Прыжок переносит на две клетки по текущему направлению. Промежуточная клетка перескакивается, а приземление должно быть свободным. После первого прыжка второй начинается уже из новой позиции. Поэтому перед циклом проверь все места приземления, а не только первое. Число повторов выбирай по маршруту, чтобы не выйти за карту.", "example": "Два прыжка вправо перемещают на четыре клетки, если оба приземления допустимы. Из другой стартовой клетки тот же цикл может привести за границу карты.", "goal": "Доведи дрона до цели, проверив повторяющиеся прыжки.", "steps": ["Найди старт, направление и возможные места приземления.", "Запиши повторение с двоеточием и отступом; проверь позицию после каждого прыжка.", "Запусти программу и исправь число повторов или маршрут при ошибке."], "success": "Дрон достиг цели без опасного приземления и выхода за карту."},
  'g4_l57': {"concept": "Рисуем квадрат повторением", "explanation": "Геометрический узор можно задать последовательностью движений и поворотов. У квадрата четыре равные стороны и четыре прямых угла. После рисования стороны нужно повернуть в том же направлении, чтобы начать следующую. Полный поворот за обход фигуры составляет 360 градусов. Разделив его на четыре одинаковых поворота, получаем угол одного поворота. Равные шаги также важны: одних правильных углов недостаточно для квадрата.", "example": "Чтобы обойти прямоугольник, чередуют длины 3 и 2 шага, поворачивая на прямой угол. Для квадрата все четыре длины одинаковы, поэтому можно повторить один участок.", "goal": "Выбери угол поворота после каждой стороны квадрата.", "steps": ["Вспомни число сторон и полный оборот.", "Раздели 360 градусов на четыре одинаковых поворота.", "Выбери результат."], "success": "Выбран прямой угол 90 градусов."},
  'g4_l58': {"concept": "Собираем понятный экран проекта", "explanation": "Красивый рисунок не заменяет понятную структуру экрана. Игроку нужно увидеть своё состояние, основное содержание и доступное действие. Для них предназначены верхняя панель, главная область и область действия. Детали подбирают по назначению, а не только по внешнему виду. В этой практике ты собираешь макет из готовых деталей. Рисовать пиксельную картинку или создавать инфографику здесь не требуется.", "example": "На экране игры сведения об игроке находятся сверху, герой — в главной области, запуск — в области действия. Если поставить управление вместо героя, структура станет непонятной.", "goal": "Заполни требуемые области макета подходящими деталями.", "steps": ["Прочитай назначение деталей и названия областей.", "Выбери деталь и подходящую область либо перетащи её.", "После заполнения нажми «Запустить приложение»."], "success": "Все области заполнены, экран успешно запущен."},
  'g4_l59': {"concept": "Готовим зрителя к движению", "explanation": "Анимация должна помогать понять, что делает персонаж. Небольшое движение перед основным действием называют подготовкой. Перед прыжком герой может присесть, перед броском — замахнуться. Зритель замечает намерение, и следующее движение становится понятнее. Такая подготовка относится к последовательности кадров, а не к уменьшению размера файла. Её длительность должна подходить действию и управлению.", "example": "Перед броском герой отводит руку назад, затем бросает мяч. Если сразу показать мяч в полёте, зрителю труднее заметить, кто и когда его бросил.", "goal": "Определи, зачем персонаж приседает перед прыжком.", "steps": ["Свяжи предварительное движение с будущим действием.", "Отдели выразительность анимации от размера файла и заряда батареи.", "Выбери ответ о подготовке."], "success": "Выбрана подготовка к действию."},
  'g4_l60': {"concept": "Оформляем заголовок портфолио", "explanation": "Портфолио показывает выбранные работы и помогает рассказать, чему ты научился. Главный заголовок обозначают тегом h1. Цвет его букв задаёт CSS-свойство color. Оно не меняет фон страницы и не добавляет новые работы. В этой небольшой практике проверяется заголовок с цветом lime. Не нужно создавать целый сайт, чтобы выполнить это условие.", "example": "<h1 style=\"color: orange;\">Мои проекты</h1> задаёт оранжевый текст заголовка. Для твоего заголовка используй цвет из задания, сохранив понятное название.", "goal": "Создай главный заголовок h1 с цветом текста lime.", "steps": ["Найди или добавь парный тег h1 с названием портфолио.", "Задай color для этого заголовка, используя требуемый цвет.", "Запусти проверку и сравни код с предпросмотром."], "success": "Найден h1, его цвет текста соответствует условию."},
  'g4_l61': {"concept": "Защищаем время для задачи", "explanation": "Уведомления прерывают внимание и побуждают переключаться. Возвращение к задаче тоже требует усилий. Перед работой можно отключить необязательные уведомления или включить «Не беспокоить». Договорись со взрослым, какие важные звонки должны оставаться доступными. Такой режим помогает сосредоточиться, но не гарантирует одинаковую скорость всем. Выдели время для работы и отдельное время для проверки сообщений.", "example": "Ты читаешь условие, а телефон предлагает открыть чат. Можно заранее заглушить необязательные сигналы на время задачи и посмотреть сообщения после выбранного этапа.", "goal": "Выбери действие, уменьшающее отвлечение уведомлениями.", "steps": ["Определи, что именно прерывает работу.", "Сравни уменьшение сигналов с частой проверкой сообщений.", "Выбери подходящий способ."], "success": "Выбран режим, ограничивающий отвлекающие уведомления."},
  'g4_l62': {"concept": "Проверяем сенсацию за пределами чата", "explanation": "Пересланное сообщение не становится доказанным фактом из-за числа пересылок. Найди, кто сделал исходное утверждение и на какие данные он ссылается. Латеральное чтение означает поиск сведений о сообщении и источнике за пределами самой публикации. Сравни утверждение с подходящими надёжными источниками. Если подтверждения нет, не передавай сообщение как установленный факт. Советы о здоровье из чата обсуждай со взрослым, а не проверяй на себе.", "example": "Сообщение обещает чудесное свойство продукта, но не называет исследование. Начни с поиска исходного источника: красивый заголовок и фраза «учёные доказали» его не заменяют.", "goal": "Оцени, можно ли доверять сенсационному сообщению без подтверждения.", "steps": ["Найди утверждение и проверь, назван ли исходный источник.", "Подумай, чем можно подтвердить такое обещание.", "Выбери оценку достоверности и прочитай разбор."], "success": "Выбран ответ, не принимающий неподтверждённое обещание за факт."},
  'g4_l63': {"concept": "Помогаем, когда видим травлю", "explanation": "Повторяющиеся унижения в сети могут причинять вред. Свидетель может не поддерживать обидчика и обратиться за помощью. Не ставь одобрительные реакции на оскорбления и не распространяй их. Пострадавшему можно написать слова поддержки отдельно. Покажи ситуацию доверенному взрослому; при необходимости помоги сохранить сообщения для обращения. Отвечать такой же грубостью может усилить конфликт.", "example": "В чате высмеивают одноклассника. Вместо участия в насмешках можно написать ему «Я рядом» и рассказать учителю, что происходит. Не нужно одному вступать в опасный спор.", "goal": "Выбери действие человека, который поддерживает пострадавшего.", "steps": ["Найди вариант с поддержкой и обращением к взрослому.", "Исключи поощрение обидчика и ответные оскорбления.", "Выбери безопасное действие."], "success": "Выбраны поддержка и помощь взрослого."},
  'g4_l64': {"concept": "Личные сведения в открытом сообществе", "explanation": "Открытые сообщения могут увидеть люди, которых ты не знаешь. Домашний адрес, телефон и сведения о школе помогают найти человека вне игры. Игровой ник тоже лучше выбирать без настоящего имени и даты рождения. Не публикуй чужие личные данные и проверь, нет ли их на скриншоте. Интересы и игровые обсуждения обычно не требуют указания места проживания. Если сомневаешься, сначала спроси взрослого.", "example": "На скриншоте достижения виден игровой чат с номером телефона. Перед публикацией такой снимок нужно изменить или не отправлять: личные данные не относятся к достижению.", "goal": "Найди сведения, которые опасно публиковать в открытом игровом сообществе.", "steps": ["Отличи сведения о месте проживания и контактах от обсуждения игры.", "Подумай, что позволяет найти человека вне сети.", "Выбери вариант с личными данными."], "success": "Выбраны адрес и другие личные сведения."},
  'g4_l65': {"concept": "Не соглашаемся на опасный секрет", "explanation": "В игре человек может представиться кем угодно. Подарок не делает незнакомца надёжным. Просьба прислать адрес и скрыть разговор от взрослых — причина остановиться. Не отправляй домашний адрес, адрес школы или фотографии для подтверждения. Прекрати разговор и покажи его доверенному взрослому. Если уже что-то отправил, всё равно обратись за помощью: исправлять ситуацию нужно вместе.", "example": "Знакомый из чата обещает приз, но требует место встречи и секрет. Не торгуйся за подарок и не подменяй адрес другим: безопасное действие — остановиться и рассказать взрослому.", "goal": "Выбери безопасную реакцию на просьбу об адресе и тайне.", "steps": ["Найди опасные признаки: личные сведения и скрытность.", "Исключи отправку любого адреса и договорённости о подарках.", "Выбери прекращение общения и помощь взрослого."], "success": "Выбран отказ и обращение к родителю или другому доверенному взрослому."},
  'g4_l66': {"concept": "Разрешения должны иметь понятную цель", "explanation": "Разрешение даёт приложению доступ к определённой возможности устройства. Например, микрофон нужен для записи голоса, контакты — для работы с адресной книгой. Запрос разрешения не означает, что его обязательно нужно принять. Сравни доступ с задачей приложения. Если простая головоломка не объясняет, зачем ей контакты и микрофон, откажи и обсуди со взрослым. Выключение звука не отзывает доступ к микрофону.", "example": "Приложение для записи рассказа объясняет, зачем нужен микрофон. Калькулятор просит тот же доступ без объяснения: это повод остановиться и проверить назначение запроса.", "goal": "Оцени запрос контактов и микрофона простой головоломкой.", "steps": ["Определи, что делает приложение и какие возможности действительно нужны.", "Проверь, объяснена ли причина доступа.", "Выбери отказ в ненужных разрешениях и прочитай разбор."], "success": "Выбран отказ в доступе, не связанном с задачей приложения."},
  'g4_l67': {"concept": "Указываем автора и условия использования", "explanation": "Чужая работа не становится свободной для любого использования только потому, что найдена в интернете. Лицензия сообщает, на каких условиях автор разрешает её использовать. CC BY разрешает использование при соблюдении условий указания авторства. Сохрани имя автора, источник и ссылку на лицензию; при изменениях отметь их. Другие пометки лицензии могут добавлять ограничения. Если условий не нашёл, не считай это разрешением.", "example": "Для рисунка с CC BY подпиши автора, добавь ссылку на источник и лицензию. Если изменил цвета, отметь изменение. Подпись «из интернета» не указывает создателя работы.", "goal": "Выбери основное условие использования работы с CC BY.", "steps": ["Найди пометку BY и её связь с указанием авторства.", "Исключи варианты об отсутствии любых условий.", "Выбери ответ и прочитай пояснение."], "success": "Выбран ответ с указанием автора и соблюдением лицензии."},
  'g4_l68': {"concept": "Понятный макет для разных пользователей", "explanation": "Доступность помогает людям с разными возможностями пользоваться интерфейсом. Понятные подписи, читаемый текст и заметное главное действие облегчают работу. Нельзя передавать важный смысл только цветом. В макете сначала проверь назначение областей и соответствие деталей. Этот тренажёр проверяет структуру экрана; полноценная проверка доступности требует и других действий. После сборки подумай, будет ли назначение каждого элемента понятно без подсказки.", "example": "Кнопка с одной зелёной точкой может быть непонятной. Подпись «Начать» объясняет действие независимо от различения цветов. Размещение в области главного действия также помогает ориентироваться.", "goal": "Собери макет с понятной структурой и подходящими деталями.", "steps": ["Прочитай названия деталей и областей.", "Помести сведения сверху, главное содержание и действие — в свои области.", "После заполнения нажми «Запустить приложение» и оцени понятность назначения элементов."], "success": "Структура макета принята тренажёром."},
  'g4_l69': {"concept": "Защищаем системы с разрешения", "explanation": "Специалист по кибербезопасности помогает защищать данные и системы. Он ищет слабые места, проверяет защиту и предлагает исправления. Проверки проводятся с разрешения владельца и в согласованных границах. Доступность чужого сайта не является разрешением его взламывать. Важно сообщить о найденной проблеме ответственно, не раскрывая чужие данные. Защита требует не только технических знаний, но и аккуратного отношения к людям.", "example": "Школа разрешила специалисту проверить учебный стенд. Он работает только на этом стенде, описывает проблему и предлагает исправление; чужие аккаунты в проверку не входят.", "goal": "Выбери задачу специалиста по кибербезопасности.", "steps": ["Отдели защиту и разрешённую проверку от взлома чужих аккаунтов.", "Найди вариант о поиске уязвимостей и защите данных.", "Выбери ответ и прочитай разбор."], "success": "Выбран ответ о защите и разрешённом поиске уязвимостей."},
  'g4_l70': {"concept": "Наши правила работы в сети", "explanation": "Цифровой договор — общие правила, которые помогают учиться и общаться. Вежливость означает помнить, что по другую сторону экрана тоже человек. Проверка источников помогает не распространять ложные сведения. Бережное отношение к данным означает не публиковать чужие секреты и контакты. При непонятной или опасной ситуации можно остановиться и попросить помощь. Полезно договориться об этих действиях заранее, а не только после ошибки.", "example": "Перед отправкой комментария перечитай его: помог бы он человеку при разговоре рядом? Если сообщение обижает или раскрывает личные данные, измени его или не отправляй.", "goal": "Выбери правило уважительного общения в интернете.", "steps": ["Сравни предложенные действия с безопасностью и уважением к людям.", "Отдели полезное правило от доверия любым новостям и загрузкам.", "Выбери вежливое общение."], "success": "Выбрано правило уважительного общения."},
};
